<?php use App\Support\Ui; ?>
<div class="page-heading"><div><span class="eyebrow">TOOL INTERVIEWS</span><h1>Support team</h1><p>Keep assignment capacity current without disrupting future interviews.</p></div><span class="badge neutral"><?= count($people) ?> people</span></div><?php if(isset($errors['form'])):?><div class="alert danger" role="alert"><?= $e($errors['form']) ?></div><?php endif; ?>
<div class="directory-grid"><section class="card"><div class="card-heading"><div><h2>Support directory</h2><p>Live workload, with no reporting overhead.</p></div></div><div class="management-list"><?php foreach($people as $p):?><form method="post" action="<?= $e($url('admin/support')) ?>" class="management-row support-row"><?= Ui::csrf() ?><input type="hidden" name="id" value="<?= $e($p['id']) ?>"><span class="avatar soft"><?= $e(\App\Support\View::initials($p['name'])) ?></span><div class="field"><label for="pn<?= $e($p['id']) ?>">Name</label><input id="pn<?= $e($p['id']) ?>" name="name" value="<?= $e($p['name']) ?>" required></div><div class="workload"><strong><?= $e($p['today_count']) ?></strong><span>today</span></div><div class="workload"><strong><?= $e($p['upcoming_count']) ?></strong><span>upcoming</span></div><div class="field"><label for="pa<?= $e($p['id']) ?>">Status</label><select id="pa<?= $e($p['id']) ?>" name="active"><option value="1" <?= $p['active']?'selected':'' ?>>Active</option><option value="0" <?= !$p['active']?'selected':'' ?>>Inactive</option></select></div><button class="button secondary">Save</button><?php if($p['upcoming_count']):?><a class="text-link" href="<?= $e($url('admin/interviews?support_person_id='.$p['id'])) ?>">Inspect</a><?php endif;?></form><?php endforeach;?></div></section><aside class="card add-panel"><div class="card-heading"><h2>Add support person</h2></div><form method="post" action="<?= $e($url('admin/support')) ?>" class="form-stack"><?= Ui::csrf() ?><input type="hidden" name="id" value="0"><input type="hidden" name="active" value="1"><div class="field"><label for="new-person">Full name</label><input id="new-person" name="name" required></div><button class="button primary full">Add team member</button></form></aside></div>
